        ad("t", "transform length", "A power of two dividing $2r$: the length of one axis of a transform."),
        ad("\\omega_t", "synthetic root", "The root of unity $y^{2r/t}$ of order $t$ in $\\mathcal R_r$."),
        ad("B_t", "bit reversal", "The record permutation moving the entry at $j$ to the bit-reversed address $\\operatorname{rev}_a(j)$."),
        ad("J_E", "twiddle monomial", "The recordwise multiplication by $y^E$ for the combined twiddle exponent $E$."),
